<p align="justify" style="margin-bottom:0cm" id="02497838Q-c8840fcb-127680a6188e" hash="975966494"><span style="font-size:13px"><span style="font-family:Arial,Helvetica,sans-serif"><span style="font-style:normal"><span style="font-weight:normal"><span style="line-height:150%"><strong>Gabarito: <span style="color:#e74c3c">ERRADO</span></strong></span></span></span></span></span></p>

